/*
 * Native `ob` (box orientation=20) polygon vertices, in points. The port's
 * vertex generator (src/common/poly-vertices.ts, outside this module) yields
 * vertices[2].y = -18 where native has -17.999999999999996 (1 ulp); polyOverlap's
 * bounding-box test is inclusive, so a pair touching exactly at an edge flips
 * on that ulp. The verdict golden is therefore checked on the native vertices,
 * which isolates poly.c logic from the upstream rounding difference.
 */
const NATIVE_OB_VERTICES: Point[] = [
  { x: 13.646475649743008, y: 18 },
  { x: -29.264961471439033, y: 8.3935378467899842 },
  { x: -13.646475649743007, y: -17.999999999999996 },
  { x: 29.264961471439047, y: -8.3935378467899788 },
];

let graph: Graph;
let nodes: Node[];

beforeAll(() => {
  const warn = vi.spyOn(console, 'warn').mockImplementation(() => undefined);
  graph = parse(FIXTURE);
  createDefaultContext().layout(graph, 'neato');
  nodes = Array.from(graph.nodes.values());
  warn.mockRestore();
  const ob = graph.nodes.get('ob')!.info.shape_info as PolygonT;
  ob.vertices = NATIVE_OB_VERTICES.concat(ob.vertices!.slice(4));
});

afterEach(() => vi.restoreAllMocks());

function poly(n: Node, which: number): Poly {
  const p = MARGINS[which]!.run(n);
  if (p === null) throw new Error(`no polygon for ${n.name}`);
  return p;
}

function bit(verdict: string, k: number): boolean {
  return verdict[k] === '1';
}

describe('node order', () => {
  it('matches the golden dump', () => {
    expect(nodes.map((n) => n.name)).toEqual([...NODE_NAMES]);
  });
});

describe.each(MARGINS.map((m, w) => ({ ...m, w })))('$tag vs native dump', ({ tag, w }) => {
  it.each(NODE_NAMES.map((name, i) => ({ name, i })))('$name summary', ({ i }) => {
    const p = poly(nodes[i]!, w);
    const [kind, n, ox, oy, cx, cy, sx, sy] = SUMMARY[tag]![i]!;
    expect(p.kind).toBe(kind);
    expect(p.verts).toHaveLength(n!);
    expect(Math.abs(p.origin.x - ox!)).toBeLessThan(TOL);
    expect(Math.abs(p.origin.y - oy!)).toBeLessThan(TOL);
    expect(Math.abs(p.corner.x - cx!)).toBeLessThan(TOL);
    expect(Math.abs(p.corner.y - cy!)).toBeLessThan(TOL);
    expect(Math.abs(p.verts.reduce((s, v) => s + v.x, 0) - sx!)).toBeLessThan(TOL);
    expect(Math.abs(p.verts.reduce((s, v) => s + v.y, 0) - sy!)).toBeLessThan(TOL);
  });

  it.each(NODE_NAMES.map((name, i) => ({ name, i })).filter(({ name }) => `${tag}:${name}` in FULL))(
    '$name vertices',
    ({ name, i }) => {
      const expected = FULL[`${tag}:${name}`]!;
      const p = poly(nodes[i]!, w);
      expect(p.verts).toHaveLength(expected.length);
      expected.forEach(([x, y], k) => {
        expect(Math.abs(p.verts[k]!.x - x!)).toBeLessThan(TOL);
        expect(Math.abs(p.verts[k]!.y - y!)).toBeLessThan(TOL);
      });
    },
  );

  it('polyOverlap verdicts equal native for every pair and offset', () => {
    const polys = nodes.map((n) => poly(n, w));
    const rows = VERDICTS[tag]!;
    const mismatches: string[] = [];
    polys.forEach((pi, i) => {
      const cols = rows[i]!.split('|');
      polys.forEach((pj, j) => {
        OFFSETS.forEach((q, k) => {
          if (polyOverlap(ORIGIN, pi, q, pj) !== bit(cols[j]!, k)) {
            mismatches.push(`${NODE_NAMES[i]}-${NODE_NAMES[j]}@${k}`);
          }
        });
      });
    });
    expect(mismatches).toEqual([]);
  });
});

describe('kind classification', () => {
  const byName = (name: string): Node => nodes[NODE_NAMES.indexOf(name as never)]!;

  it('flags box, polygon-that-is-a-box and record as BOX', () => {
    for (const name of ['b', 'p4', 'r', 'ob', 'bw']) {
      expect(poly(byName(name), 0).kind).toBe(POLY_BOX);
    }
  });

  it('flags circle, doublecircle and point as CIRCLE, ellipse as neither', () => {
    for (const name of ['c', 'o2', 'pt']) {
      expect(poly(byName(name), 0).kind).toBe(POLY_CIRCLE);
    }
    expect(poly(byName('e'), 0).kind).toBe(0);
  });

  it('classifies a multi-periphery box-shaped polygon as BOX (only the first ring counts)', () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => undefined);
    const g = parse('graph { p [shape=polygon peripheries=2] }');
    createDefaultContext().layout(g, 'neato');
    warn.mockRestore();
    const p = g.nodes.get('p')!;
    expect(makePoly(p, 1, 1)!.kind).toBe(POLY_BOX);
    expect(makeAddPoly(p, 0.1, 0.1)!.kind).toBe(POLY_BOX);
  });

  it('uses samplepoints for rounded shapes and defaults to 20', () => {
    expect(poly(byName('sp'), 0).verts).toHaveLength(7);
    expect(poly(byName('e'), 0).verts).toHaveLength(20);
  });
});

describe('polyOverlap', () => {
  const byName = (name: string): Node => nodes[NODE_NAMES.indexOf(name as never)]!;

  it('is false for two ellipses whose bounding boxes touch but outlines do not', () => {
    const e = poly(byName('e'), 0);
    // boxes overlap in x and y (0.7 < 0.75 wide, 0.45 < 0.5 tall) near the corner
    const q = { x: 0.7, y: 0.45 };
    expect(polyOverlap(ORIGIN, e, q, e)).toBe(false);
  });

  it('is true for two boxes with intersecting bounding boxes', () => {
    const b = poly(byName('b'), 0);
    expect(polyOverlap(ORIGIN, b, { x: 0.7, y: 0.45 }, b)).toBe(true);
  });

  it('is false when bounding boxes are disjoint', () => {
    const b = poly(byName('b'), 0);
    expect(polyOverlap(ORIGIN, b, { x: 2, y: 0 }, b)).toBe(false);
  });

  it('decides circles by centre distance against the summed radii', () => {
    const c = poly(byName('c'), 0);
    expect(polyOverlap(ORIGIN, c, { x: 0.5, y: 0 }, c)).toBe(true);
    expect(polyOverlap(ORIGIN, c, { x: 0.36, y: 0.36 }, c)).toBe(false);
    expect(polyOverlap(ORIGIN, c, { x: 0.35, y: 0.35 }, c)).toBe(true);
  });

  it('detects containment of one polygon in another (no edge crossing)', () => {
    const big = poly(byName('tp'), 0);
    const small = poly(byName('pt'), 0);
    expect(polyOverlap(ORIGIN, big, { x: 0.1, y: 0.05 }, small)).toBe(true);
    expect(polyOverlap({ x: 0.1, y: 0.05 }, small, ORIGIN, big)).toBe(true);
  });
});

describe('failure and special cases', () => {
  const fake = (shape: unknown, extra: Partial<Node['info']> = {}): Node => {
    const n = Array.from(parse('graph { x }').nodes.values())[0]!;
    Object.assign(n.info, { shape, shape_info: undefined }, extra);
    return n;
  };

  it('returns null and reports an unknown shape type', () => {
    const err = vi.spyOn(console, 'error').mockImplementation(() => undefined);
    const n = fake({ name: 'epsf', kind: ShapeKind.SH_EPSF });
    expect(makePoly(n, 1, 1)).toBeNull();
    expect(makeAddPoly(n, 1, 1)).toBeNull();
    expect(err).toHaveBeenCalledWith('Error: makePoly: unknown shape type epsf\n');
    expect(err).toHaveBeenCalledWith('Error: makeAddPoly: unknown shape type epsf\n');
  });

  it('builds a BOX of the node size for a cluster node, ignoring the shape', () => {
    const n = fake({ name: 'epsf', kind: ShapeKind.SH_EPSF }, { clust: graph, width: 2, height: 1 });
    const p = makePoly(n, 1, 1)!;
    expect(p.kind).toBe(POLY_BOX);
    expect(p.verts).toEqual([{ x: 1, y: 0.5 }, { x: -1, y: 0.5 }, { x: -1, y: -0.5 }, { x: 1, y: -0.5 }]);
    const a = makeAddPoly(n, 0.25, 0.5)!;
    expect(a.verts).toEqual([{ x: 1.25, y: 1 }, { x: -1.25, y: 1 }, { x: -1.25, y: -1 }, { x: 1.25, y: -1 }]);
    expect(a.corner).toEqual({ x: 1.25, y: 1 });
    expect(a.origin).toEqual({ x: -1.25, y: -1 });
  });

  it('treats samplepoints below 3 or non-numeric as the default of 20', () => {
    for (const sp of ['2', 'abc', '']) {
      const n = fake({ name: 'point', kind: ShapeKind.SH_POINT }, { width: 1, height: 1 });
      n.attrs.set('samplepoints', sp);
      expect(makePoly(n, 1, 1)!.verts).toHaveLength(20);
    }
    const n = fake({ name: 'point', kind: ShapeKind.SH_POINT }, { width: 1, height: 1 });
    n.attrs.set('samplepoints', '9x');
    expect(makePoly(n, 1, 1)!.verts).toHaveLength(9);
  });

  it('scales a non-unit margin on the rounded verts but not at margin 1', () => {
    const n = fake({ name: 'point', kind: ShapeKind.SH_POINT }, { width: 2, height: 2 });
    const unit = makePoly(n, 1, 1)!;
    const scaled = makePoly(n, 2, 3)!;
    expect(unit.verts[0]).toEqual({ x: 1, y: 0 });
    expect(scaled.verts[0]).toEqual({ x: 2, y: 0 });
    expect(scaled.corner.y).toBeCloseTo(3, 12);
  });
});

describe('inPoly crossing rules (synthetic non-box polygons)', () => {
  /** A kind-0 Poly from CCW vertices (bbox computed as C bbox does). */
  const mk = (pts: [number, number][]): Poly => {
    const verts = pts.map(([x, y]) => ({ x, y }));
    const xs = verts.map((v) => v.x); const ys = verts.map((v) => v.y);
    return {
      origin: { x: Math.min(...xs), y: Math.min(...ys) },
      corner: { x: Math.max(...xs), y: Math.max(...ys) }, verts, kind: 0,
    };
  };
  // L-shaped outline with a horizontal edge (6,2)-(4,2) at the query's height.
  const outer = mk([[0, 0], [6, 0], [6, 2], [4, 2], [4, 4], [0, 4]]);

  it('counts a ray through two vertices as one crossing (0.5 + 0.5)', () => {
    const inner = mk([[0, 0], [0.5, -0.5], [0.5, 0.5]]);
    expect(polyOverlap({ x: 2, y: 2 }, inner, ORIGIN, outer)).toBe(true);
  });

  it('skips a horizontal edge that does not contain the query point', () => {
    const inner = mk([[0, 0], [-0.5, -0.5], [-0.5, 0.5]]);
    expect(polyOverlap({ x: 1, y: 2 }, inner, ORIGIN, outer)).toBe(true);
  });

  it('treats a query point on a horizontal edge as inside', () => {
    const inner = mk([[0, 0], [0.5, -1], [-0.5, -1]]);
    expect(polyOverlap({ x: 5, y: 2 }, inner, ORIGIN, outer)).toBe(true);
  });

  it('is false for a polygon in the notch of the L (outside, bboxes overlap)', () => {
    const inner = mk([[0, 0], [0.5, 0.5], [-0.5, 0.5]]);
    expect(polyOverlap({ x: 5, y: 3 }, inner, ORIGIN, outer)).toBe(false);
  });
});
